const holidaysFile = "holidays.yaml"

// TestHolidaysPackFile validates holidays.yaml against the rule-pack schema and checks it
// lists no hand-kept dates: the calendars are generated by rule.
func TestHolidaysPackFile(t *testing.T) {
	raw, err := os.ReadFile(holidaysFile)
	if err != nil {
		t.Fatalf("read %s: %v", holidaysFile, err)
	}
	var doc any
	if err := yaml.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("parse %s: %v", holidaysFile, err)
	}
	js, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("to json: %v", err)
	}
	var v any
	if err := json.Unmarshal(js, &v); err != nil {
		t.Fatalf("from json: %v", err)
	}
	schemaRaw, err := os.ReadFile(filepath.Join("..", "..", "..", "..", "spec", "kernel", "rulepack.schema.json"))
	if err != nil {
		t.Fatalf("read schema: %v", err)
	}
	c := jsonschema.NewCompiler()
	c.Draft = jsonschema.Draft2020
	c.AssertFormat = true
	const url = "file:///spec/kernel/rulepack.schema.json"
	if err := c.AddResource(url, bytes.NewReader(schemaRaw)); err != nil {
		t.Fatalf("add schema: %v", err)
	}
	s, err := c.Compile(url)
	if err != nil {
		t.Fatalf("compile schema: %v", err)
	}
	if err := s.Validate(v); err != nil {
		t.Fatalf("%s fails rulepack schema: %v", holidaysFile, err)
	}
	var f struct {
		TimeZone string   `yaml:"time_zone"`
		Holidays []string `yaml:"holidays"`
	}
	if err := yaml.Unmarshal(raw, &f); err != nil {
		t.Fatalf("decode %s: %v", holidaysFile, err)
	}
	if f.TimeZone != "America/Toronto" {
		t.Fatalf("time_zone = %q, want America/Toronto", f.TimeZone)
	}
	if len(f.Holidays) != 0 {
		t.Fatalf("%s lists %d dates; holidays are generated by rule", holidaysFile, len(f.Holidays))
	}
}

func dates(t *testing.T, ss ...string) []clock.Date {
	t.Helper()
	out := make([]clock.Date, 0, len(ss))
	for _, s := range ss {
		p, err := time.Parse(time.DateOnly, s)
		if err != nil {
			t.Fatalf("date %q: %v", s, err)
		}
		out = append(out, clock.Date{Year: p.Year(), Month: p.Month(), Day: p.Day()})
	}
	return out
}

// The generated court calendar reproduces the reviewed 2025-2028 r. 1.03 list date for date.
// rule: Rules of Civil Procedure r. 1.03(1) "holiday" (verify)
func TestCourtCalendarMatchesReviewedList(t *testing.T) {
	want := dates(t,
		"2025-01-01", "2025-02-17", "2025-04-18", "2025-04-21", "2025-05-19", "2025-07-01", "2025-08-04",
		"2025-09-01", "2025-10-13", "2025-11-11", "2025-12-25", "2025-12-26",
		"2026-01-01", "2026-02-16", "2026-04-03", "2026-04-06", "2026-05-18", "2026-07-01", "2026-08-03",
		"2026-09-07", "2026-10-12", "2026-11-11", "2026-12-25", "2026-12-26", "2026-12-28",
		"2027-01-01", "2027-02-15", "2027-03-26", "2027-03-29", "2027-05-24", "2027-07-01", "2027-08-02",
		"2027-09-06", "2027-10-11", "2027-11-11", "2027-12-25", "2027-12-27", "2027-12-28",
		"2028-01-01", "2028-01-03", "2028-02-21", "2028-04-14", "2028-04-17", "2028-05-22", "2028-07-01",
		"2028-07-03", "2028-08-07", "2028-09-04", "2028-10-09", "2028-11-11", "2028-11-13", "2028-12-25",
		"2028-12-26")
	if got := CourtCalendar().Holidays(2025, 2028); !slices.Equal(got, want) {
		t.Fatalf("court 2025-2028 =\n%v\nwant\n%v", got, want)
	}
}

// Each calendar answers per day: the court calendar has the Saturday substitutes, the s.87
// calendar only the Sunday ones (review B3).
// rule: Rules of Civil Procedure r. 1.03(1) "holiday" (verify)
// rule: Legislation Act, 2006 s.87 "holiday" (verify)
func TestCalendarsSplitBySource(t *testing.T) {
	tests := []struct {
		name         string
		date         string
		court, leg87 bool
	}{
		{"canada day 2028 on a saturday", "2028-07-01", true, true},
		{"monday after saturday canada day 2028", "2028-07-03", true, false},
		{"monday after saturday new year 2028", "2028-01-03", true, false},
		{"monday after saturday remembrance day 2028", "2028-11-13", true, false},
		{"monday after sunday canada day 2029", "2029-07-02", true, true},
		{"monday after sunday new year 2034", "2034-01-02", true, true},
		{"monday after sunday remembrance day 2029", "2029-11-12", true, true},
		{"christmas 2027 on a saturday: monday", "2027-12-27", true, false},
		{"christmas 2027 on a saturday: tuesday", "2027-12-28", true, false},
		{"christmas 2033 on a sunday: boxing day monday", "2033-12-26", true, true},
		{"christmas 2033 on a sunday: tuesday", "2033-12-27", true, true},
		{"christmas 2026 on a friday: monday", "2026-12-28", true, false},
		{"boxing day 2026 on a saturday", "2026-12-26", true, true},
		{"good friday 2028", "2028-04-14", true, true},
		{"easter monday 2028", "2028-04-17", true, true},
		{"good friday 2035", "2035-03-23", true, true},
		{"easter monday 2035", "2035-03-26", true, true},
		{"family day 2026", "2026-02-16", true, true},
		{"victoria day 2026", "2026-05-18", true, true},
		{"victoria day 2027 on may 24", "2027-05-24", true, true},
		{"civic holiday 2026", "2026-08-03", true, true},
		{"thanksgiving 2026", "2026-10-12", true, true},
		{"truth and reconciliation not generated (verify)", "2026-09-30", false, false},
		{"wednesday after christmas 2027", "2027-12-29", false, false},
		{"monday after christmas thursday 2025", "2025-12-29", false, false},
	}
	court := CourtCalendar().Holidays(2025, 2036)
	leg := LegislationActCalendar().Holidays(2025, 2036)
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			day := dates(t, tt.date)[0]
			if got := slices.Contains(court, day); got != tt.court {
				t.Errorf("court holiday %s = %v, want %v", tt.date, got, tt.court)
			}
			if got := slices.Contains(leg, day); got != tt.leg87 {
				t.Errorf("s.87 holiday %s = %v, want %v", tt.date, got, tt.leg87)
			}
		})
	}
}

func TestEasterSunday(t *testing.T) {
	tests := []struct {
		year int
		want string
	}{
		{2000, "2000-04-23"}, {2019, "2019-04-21"}, {2024, "2024-03-31"}, {2025, "2025-04-20"},
		{2026, "2026-04-05"}, {2027, "2027-03-28"}, {2028, "2028-04-16"}, {2029, "2029-04-01"},
		{2030, "2030-04-21"}, {2035, "2035-03-25"}, {2038, "2038-04-25"},
	}
	for _, tt := range tests {
		t.Run(tt.want, func(t *testing.T) {
			if got := easterSunday(tt.year); got.String() != tt.want {
				t.Fatalf("easter %d = %s, want %s", tt.year, got, tt.want)
			}
		})
	}
}

// Each of the 12 named holidays lands on a weekday or moves to a court substitute; Christmas
// and Boxing Day share substitutes, so every year has 12 weekday court closures.
func TestCourtCalendarWeekdayCountPerYear(t *testing.T) {
	for y := 2025; y <= 2045; y++ {
		n := 0
		for _, h := range CourtCalendar().Holidays(y, y) {
			wd := h.Start(time.UTC).Weekday()
			if wd != time.Saturday && wd != time.Sunday {
				n++
			}
			if h.Year != y {
				t.Errorf("%d: holiday %s outside the year", y, h)
			}
		}
		if n != 12 {
			t.Errorf("weekday court holidays in %d = %d, want 12", y, n)
		}
	}
}

// The s.87 calendar is the named holidays plus Sunday substitutes, so it is a subset of the
// court calendar: a limitation date never rolls where a court date would not.
func TestLegislationActCalendarIsSubsetOfCourt(t *testing.T) {
	court := CourtCalendar().Holidays(2025, 2045)
	for _, h := range LegislationActCalendar().Holidays(2025, 2045) {
		if !slices.Contains(court, h) {
			t.Errorf("s.87 holiday %s is not a court holiday", h)
		}
	}
}

// Holidays and LegislationActHolidays cover the previous year through ten years ahead.
func TestHolidaysRollingWindow(t *testing.T) {
	loc, err := time.LoadLocation(clock.DefaultZone)
	if err != nil {
		t.Fatal(err)
	}
	from, to := Window(clock.DateOf(time.Now(), loc))
	if to-from != WindowYears+1 || WindowYears != 10 {
		t.Fatalf("window %d-%d, want previous year plus %d ahead", from, to, WindowYears)
	}
	court, err := Holidays()
	if err != nil {
		t.Fatalf("Holidays: %v", err)
	}
	if !slices.Equal(court, CourtCalendar().Holidays(from, to)) {
		t.Fatal("Holidays() is not the court calendar over the window")
	}
	leg, lf, lt, err := LegislationActHolidays()
	if err != nil {
		t.Fatalf("LegislationActHolidays: %v", err)
	}
	if lf != from || lt != to || !slices.Equal(leg, LegislationActCalendar().Holidays(from, to)) {
		t.Fatalf("LegislationActHolidays covers %d-%d, want %d-%d", lf, lt, from, to)
	}
	if court[0].Year != from || court[len(court)-1].Year != to {
		t.Fatalf("court calendar spans %s to %s, want %d to %d", court[0], court[len(court)-1], from, to)
	}
}
